/** @param {number} value @param {number} [max] */
function clampRelationshipValue(value, max) {
    const m = max ?? getNpcRelationshipMax();
    const n = Number(value);
    if (!Number.isFinite(n)) return 0;
    return Math.max(-m, Math.min(m, Math.round(n)));
}

