// ── src/state/relationship-math.js: lerpTier ──
/** @param {number} a @param {number} b @param {number} t */
function lerpTier(a, b, t) {
    return a + (b - a) * t;
}

// ── src/state/relationship-math.js: getRelTierIntensity ──
/**
 * Intensity 0–1 from absolute value vs configured max.
 * @param {number} value
 * @param {number} [max]
 */
function getRelTierIntensity(value, max) {
    const m = max ?? getNpcRelationshipMax();
    if (m <= 0) return 0;
    const v = clampRelationshipValue(value, m);
    if (v === 0) return 0;
    return Math.abs(v) / m;
}

