/**
 * @typedef {{ type: 'relationship_delta', npc: string, field: 'friendship'|'affection', delta: number, reason?: string }} RelationshipDeltaCommand
 */

/**
 * Removes the optional [RELATIONS] command block from a State Tracker response
 * and returns the remaining memo text plus validated commands. This deliberately
 * uses line/token parsing rather than a relationship regex: only the command
 * block is interpreted, while NPC names remain free-form.
 *
 * @param {string} response
 * @returns {{ memo: string, commands: RelationshipDeltaCommand[] }}
 */
function extractStateTrackerRelationshipCommands(response) {
    const source = typeof response === 'string' ? response : '';
    const commands = [];

    // Remove every relationship block before memo processing. An unclosed block is
    // deliberately treated as extending to the end of the response: losing a malformed
    // command is safer than leaking command syntax into persisted tracker state.
    const memo = source.replace(/\[RELATIONS\]([\s\S]*?)(?:\[\/RELATIONS\]|$)/gi, (_match, block) => {
        for (const line of block.split('\n')) {
            const command = parseRelationshipCommandLine(line);
            if (command) commands.push(command);
        }
        return '';
    }).trim();

    return { memo, commands };
}

/** @param {string} line @returns {RelationshipDeltaCommand|null} */
function parseRelationshipCommandLine(line) {
    const parts = String(line || '').trim().replaceAll('\t', ' ').split(' ').filter(Boolean);
    if (parts.length < 2) return null;

    const firstToken = parts.shift()?.toLowerCase() || '';
    let field = firstToken;
    let deltaText = '';
    for (const axis of ['friendship', 'affection']) {
        if (firstToken.startsWith(axis) && firstToken !== axis) {
            field = axis;
            deltaText = firstToken.slice(axis.length);
            break;
        }
    }
    if (!deltaText) deltaText = parts.shift() || '';
    const delta = Number(deltaText);
    const npc = parts.join(' ').trim();

    if ((field !== 'friendship' && field !== 'affection') || !Number.isSafeInteger(delta) || delta === 0 || !npc) {
        return null;
    }

    return { type: 'relationship_delta', npc, field, delta };
}

// ── src/state/relationship-prompts.js: buildStateTrackerRelationshipCommandInstruction ──
/**
 * State Tracker instruction for tag-based, code-applied relationship changes.
 * @param {number} [max]
 * @param {boolean} [isFullContext]
 * @param {string} [customPrompt]
 * @returns {string}
 */
function buildStateTrackerRelationshipCommandInstruction(max, isFullContext = false, customPrompt = '') {
    const m = max ?? getNpcRelationshipMax();
    const fullAuditRule = isFullContext
        ? 'This is a full-history audit, so do not emit a [RELATIONS] block. Do not replay historical relationship changes.'
        : 'The GM narrator is authoritative for relationship points. Only convert its explicit relationship annotations; never infer, award, adjust, or omit a delta yourself.';

    if (typeof customPrompt === 'string' && customPrompt.trim()) {
        return customPrompt.trim()
            .replaceAll('{{max}}', String(m))
            .replaceAll('{{full_audit_rule}}', fullAuditRule);
    }

    return `## RELATIONSHIP DELTA COMMANDS
${fullAuditRule}

Emit this block only when there is at least one qualifying change:
[RELATIONS]
Friendship +5 Exact NPC Name
Affection -2 Exact NPC Name
[/RELATIONS]

Typical narrator annotations look like:
*(Friendship: Marcus +10 — saved his life in the alley)*
*(Affection: Elena +2 — she seemed touched by the compliment)*

Record a delta when the narrator's intent to award relationship points is clear, even if its punctuation, wording, capitalization, spacing, or surrounding formatting is slightly different from these examples. Do not invent a relationship award when that intent is unclear.

Each command is one line: axis first (Friendship or Affection), signed whole-number delta second, then the NPC name. Preserve the intended axis, NPC, and delta; discard only the explanation. Do not add reasons, bullets, punctuation, or any other text inside the block. If there are no clear narrator relationship awards, do not output a [RELATIONS] block. Each command is clamped to -${m} through +${m}.`;
}

